        local function vdPrivacyAsset(value)
            if type(value) == "number" then value = tostring(value) end
            if type(value) ~= "string" then return "" end
            value = value:match("^%s*(.-)%s*$") or ""
            if value == "" then return "" end
            if value:match("^%d+$") then return "rbxassetid://" .. value end
            local lower = value:lower()
            if lower:match("^rbxassetid://%d+$")
                or lower:match("^rbxasset://")
                or lower:match("^rbxthumb://")
                or lower:match("^rbxgameasset://") then
                return value
            end
             
            local id = lower:match("^https?://www%.roblox%.com/asset/%?id=(%d+)$")
                or lower:match("^https?://roblox%.com/asset/%?id=(%d+)$")
            if id then return "rbxassetid://" .. id end
            return ""
        end

         
         
